<?php require dirname(__DIR__).'/config/bootstrap.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();try{Auth::register($_POST['name']??'',$_POST['email']??'',$_POST['password']??'');Auth::login($_POST['email'],$_POST['password']);redirect('/account/');}catch(Throwable $e){$err='Registration failed. Email may already exist or password is too short.';}}?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/store.css"></head><body><main class="panel narrow"><h1>Create account</h1><p class="error"><?=e($err)?></p><form method="post"><?=Security::field()?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="10" required></label><button>Register</button></form><a href="/auth/login.php">Login</a></main></body></html>